import { NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';
import { ALL_UNIVERSITIES } from '@/data/universities';
import { existsSync, readFileSync, readdirSync } from 'fs';

import { join } from 'path';
import sharp from 'sharp';

const DEFINITELY_NOT_LOGO = ['wide', 'campus', 'aerial', 'panorama', 'university college london', 'background'];
const GOOD_LOGO_KEYWORDS = ['tekst', 'text', 'horizontal', 'fullname', 'fullcolour', 'full-colour', 'full colour', 'manchester - logo', 'logo - tekst', 'imperial_logo', 'logo-tekst'];

function scoreFile(f: string): number {
    const fl = f.toLowerCase();
    if (DEFINITELY_NOT_LOGO.some(kw => fl.includes(kw))) return -999;
    let s = 0;
    if (GOOD_LOGO_KEYWORDS.some(kw => fl.includes(kw))) s += 100;
    if (fl.includes('icon')) s -= 10;
    if (fl.includes('crest')) s -= 5;
    // Prefer colour logos over black/monochrome
    if (fl.includes('colour') || fl.includes('color') || fl.includes('fullcolour') || fl.includes('full-colour')) s += 10;
    if (fl.includes('black') || fl.includes('white') || fl.includes('singlecolour') || fl.includes('monochrome')) s -= 10;
    if (fl.endsWith('.svg')) s += 20;
    if (fl.endsWith('.png')) s += 10;
    if (fl.endsWith('.webp')) s += 5;
    if (fl.endsWith('.jpg') || fl.endsWith('.jpeg')) s -= 5;
    return s;
}

async function rasterHasBg(filePath: string): Promise<boolean> {
    try {
        const img = sharp(filePath);
        const { width, height, channels } = await img.metadata();
        if (!width || !height) return false;
        const PATCH = 6;
        const corners = [
            { left: 0, top: 0 },
            { left: Math.max(0, width - PATCH), top: 0 },
            { left: 0, top: Math.max(0, height - PATCH) },
            { left: Math.max(0, width - PATCH), top: Math.max(0, height - PATCH) },
        ];
        const hasAlphaChannel = channels && channels >= 4;
        let totalAlpha = 0;
        for (const corner of corners) {
            const raw = await sharp(filePath)
                .extract({ left: corner.left, top: corner.top, width: PATCH, height: PATCH })
                .raw()
                .toBuffer({ resolveWithObject: true });
            const data = raw.data;
            const stride = hasAlphaChannel ? 4 : 3;
            const pixCount = data.length / stride;
            let patchAlpha = 0;
            for (let i = 0; i < data.length; i += stride) {
                patchAlpha += hasAlphaChannel ? data[i + 3] : 255;
            }
            totalAlpha += patchAlpha / pixCount;
        }
        const avgAlpha = totalAlpha / corners.length;
        return !hasAlphaChannel || avgAlpha >= 240;
    } catch { return false; }
}

async function imageIsLight(filePath: string): Promise<boolean> {
    try {
        const raw = await sharp(filePath).resize(32, 32, { fit: 'fill' }).raw().toBuffer({ resolveWithObject: true });
        const data = raw.data;
        const stride = raw.info.channels;
        let totalLuma = 0;
        let count = 0;
        let diffs = 0;
        let lastLuma = -1;

        for (let i = 0; i < data.length; i += stride) {
            const r = data[i], g = data[i+1], b = data[i+2], a = stride >= 4 ? data[i+3] : 255;
            if (a > 20) { // Slight alpha threshold
                const luma = (0.299 * r + 0.587 * g + 0.114 * b);
                totalLuma += luma;
                count++;
                if (lastLuma !== -1) diffs += Math.abs(luma - lastLuma);
                lastLuma = luma;
            }
        }

        // If the image is basically one solid color (no variation), it might be "empty" or a background block
        if (count > 0 && diffs === 0 && (totalLuma / count) > 250) return true; // Pure white square

        return count === 0 ? true : (totalLuma / count) > 130;
    } catch {
        const f = filePath.toLowerCase();
        return f.includes('white') || f.includes('light') || f.includes('inv') || f.includes('hvit');
    }
}

async function isLogoEmpty(filePath: string): Promise<boolean> {
    try {
        const stats = await sharp(filePath).stats();
        // If standard deviation is extremely low across all channels
        const totalStdev = stats.channels.reduce((acc, c) => acc + c.stdev, 0);
        if (totalStdev < 1) return true; // Less than 1 is basically a solid block
        return false;
    } catch { return false; }
}

async function getLogoColor(filePath: string): Promise<string | null> {
    try {
        const { data, info } = await sharp(filePath).resize(100, 100, { fit: 'inside' }).raw().toBuffer({ resolveWithObject: true });
        const stride = info.channels;
        const colorCounts: Record<string, number> = {};
        for (let i = 0; i < data.length; i += stride) {
            const r = data[i], g = data[i+1], b = data[i+2], a = stride >= 4 ? data[i+3] : 255;
            if (a < 128) continue;
            if (r > 240 && g > 240 && b > 240) continue;
            const hex = `#${r.toString(16).padStart(2,'0')}${g.toString(16).padStart(2,'0')}${b.toString(16).padStart(2,'0')}`;
            colorCounts[hex] = (colorCounts[hex] || 0) + 1;
        }
        const sorted = Object.entries(colorCounts).sort((a,b) => b[1] - a[1]);
        return sorted[0]?.[0] || null;
    } catch { return null; }
}

async function getAllLogos(basePath: string, folder: string, domain: string, campus?: string | null): Promise<Array<{
    url: string; hasBg: boolean; isIcon: boolean; isText: boolean; score: number; filename: string; isLight: boolean; logoColor: string | null;
}>> {
    const rootLogoDir = join(basePath, folder, 'Logo');
    if (!existsSync(rootLogoDir)) return [];

    let logoDir = rootLogoDir;
    if (campus) {
        const campusLogoPath = join(rootLogoDir, campus);
        if (campusLogoPath.startsWith(rootLogoDir) && existsSync(campusLogoPath)) {
            logoDir = campusLogoPath;
        }
    }

    const files = readdirSync(logoDir)
        .filter(f => /\.(png|svg|webp|jpg|jpeg)$/i.test(f) && !f.startsWith('.'))
        .filter(f => scoreFile(f) > -500);

    const results = await Promise.all(files.map(async (f) => {
        const logoPath = join(logoDir, f);
        if (await isLogoEmpty(logoPath)) return null;

        const ext = f.split('.').pop()?.toLowerCase() ?? '';
        const isIcon = f.toLowerCase().includes('icon') || f.toLowerCase().includes('crest');
        let hasBg = ext === 'jpg' || ext === 'jpeg';
        if (!hasBg && (ext === 'png' || ext === 'webp')) hasBg = await rasterHasBg(logoPath);
        const isLight = await imageIsLight(logoPath);
        const logoColor = await getLogoColor(logoPath);

        // Let's add a smart hint for background preferences
        let preferredBg: string | null = null;
        if (f.toLowerCase().includes('hvit teskt')) {
            preferredBg = '#575756'; // Specifically for NTNU's request
        } else if (f.toLowerCase().includes('henley') && f.toLowerCase().includes('white')) {
            preferredBg = '#1E3582'; // Henley Blue
        } else if (folder === 'LSE' && (isLight || f.toLowerCase().includes('white') || f.toLowerCase().includes('light'))) {
            preferredBg = '#f33131'; // Force new LSE Red background for LSE light logos
        }

        // We only want the relative filename to re-fetch via api/full-logo
        // But if it's in a subfolder, we need that path segment
        const fileParam = (logoDir !== rootLogoDir && campus) ? join(campus, f) : f;

        return {
            url: `/api/full-logo?domain=${domain}&file=${encodeURIComponent(fileParam)}&v=${Date.now()}`,
            hasBg, isLight, logoColor, isIcon, isText: !isIcon, score: scoreFile(f), filename: f,
            preferredBg
        };
    }));
    return (results.filter(r => r !== null) as any[]).sort((a, b) => b.score - a.score);
}

function getImageFiles(basePath: string, folder: string, campus?: string | null): string[] {
    const rootDir = join(basePath, folder, 'Bilder_HighRez');
    if (!existsSync(rootDir)) return [];

    let targetDir = campus 
        ? join(rootDir, campus)
        : rootDir;

    // Handle character normalization (NFC vs NFD) for folders like "Ås" or "Bodø"
    if (!existsSync(targetDir)) {
        const nfc = targetDir.normalize('NFC');
        const nfd = targetDir.normalize('NFD');
        if (existsSync(nfc)) targetDir = nfc;
        else if (existsSync(nfd)) targetDir = nfd;
        else if (!campus) return []; // Root doesn't exist even with norm
        else targetDir = rootDir; // Fallback to root if campus folder literally not found
    }

    function walk(d: string): string[] {
        let results: string[] = [];
        const items = readdirSync(d, { withFileTypes: true });
        for (const item of items) {
            const fullPath = join(d, item.name);
            if (item.isDirectory()) {
                results = results.concat(walk(fullPath));
            } else if (/\.(jpe?g|png|webp|avif)$/i.test(item.name) && !item.name.toLowerCase().includes('with logo')) {
                // Get the path relative to rootDir to reconstruct the file param
                const relPath = fullPath.replace(rootDir + '/', '');
                const root = basePath.split('/').pop() || '';
                const encodedFolder = folder.split('/').map(encodeURIComponent).join('/');
                const encodedRel = relPath.split('/').map(encodeURIComponent).join('/');
                results.push(`/${root}/${encodedFolder}/Bilder_HighRez/${encodedRel}`);
            }
        }
        return results;
    }

    return walk(targetDir);
}

function getBrand(basePath: string, folder: string) {
    const jsonDir = join(basePath, folder, 'Brand_Farger_Fonter');
    if (!existsSync(jsonDir)) return null;
    const file = readdirSync(jsonDir).find(f => f.endsWith('.json'));
    if (!file) return null;
    try {
        return JSON.parse(readFileSync(join(jsonDir, file), 'utf8'));
    } catch { return null; }
}

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const query = searchParams.get('domain')?.toLowerCase().trim() || searchParams.get('q')?.toLowerCase().trim() || '';
    const campus = searchParams.get('campus')?.normalize('NFC') ?? null;
    if (!query) return NextResponse.json({ error: 'No query' }, { status: 400 });

    const match = ALL_UNIVERSITIES.find(u =>
        u.domain === query || u.name.toLowerCase() === query || u.short?.toLowerCase() === query
    ) ?? ALL_UNIVERSITIES.find(u =>
        u.name.toLowerCase().includes(query) || u.short?.toLowerCase().includes(query) || u.domain.toLowerCase().includes(query)
    );

    if (!match) return NextResponse.json({ error: 'University not found' }, { status: 404 });

    const cacheDir = join(process.cwd(), 'src', 'data', 'cache');
    const cachePath = join(cacheDir, `${match.domain}${campus ? `-${campus}` : ''}.json`);

    // ── CACHE CHECK ──────────────────────────────────────────
    if (existsSync(cachePath)) {
        try {
            const cached = JSON.parse(readFileSync(cachePath, 'utf8'));
            // Still check for fresh image files (in case they were added) but skip the sharp analysis
            return NextResponse.json(cached);
        } catch { /* proceed to re-analyze */ }
    }

    const basePath = join(process.cwd(), 'public', match.root);
    const brand = getBrand(basePath, match.folder);
    const images = getImageFiles(basePath, match.folder, campus);
    const logos = await getAllLogos(basePath, match.folder, match.domain, campus);
    const colors: string[] = brand?.colors?.map((c: { hex: string }) => c.hex) ?? ['#003865'];
    const fonts: string[] = brand?.fonts?.map((f: { name: string }) => f.name) ?? ['Inter'];

    const bestTextLogo = logos.find(l => l.isText) ?? logos[0];
    const bestIconLogo = logos.find(l => l.isIcon) ?? logos[logos.length - 1] ?? logos[0];

    const finalData = {
        name: match.short || match.name,
        fullName: match.name,
        domain: match.domain,
        folder: match.folder,
        root: match.root,
        logo: `/api/logo?domain=${match.domain}`,
        fullLogo: (bestTextLogo?.url ?? `/api/full-logo?domain=${match.domain}&v=${Date.now()}`) + "&w=800",
        iconLogo: bestIconLogo?.url ? (bestIconLogo.url + "&w=800") : undefined,
        logoHasBg: bestTextLogo?.hasBg ?? false,
        logos: logos.map(l => ({ ...l, url: l.url + "&w=800" })), 
        colors, 
        fonts, 
        images,
    };

    // ── SAVE TO CACHE ───────────────────────────────────────
    try {
        if (!existsSync(cacheDir)) {
          const fs = require('fs');
          fs.mkdirSync(cacheDir, { recursive: true });
        }
        const fs = require('fs');
        fs.writeFileSync(cachePath, JSON.stringify(finalData), 'utf8');
    } catch (e) { console.error("Cache write failed:", e); }

    return NextResponse.json(finalData);
}

import { existsSync, readFileSync, readdirSync } from 'fs';

export const dynamic = 'force-dynamic';
import { join } from 'path';
import { ALL_UNIVERSITIES } from '@/data/universities';
import sharp from 'sharp';

const DEFINITELY_NOT_LOGO = [
    'wide', 'campus', 'aerial', 'panorama', 'university college london', 'background',
];

const GOOD_LOGO_KEYWORDS = [
    'tekst', 'text', 'horizontal', 'fullname', 'fullcolour', 'full-colour',
    'full colour', 'manchester - logo', 'logo - tekst', 'imperial_logo - tekst',
    'logo - tekst', 'logo-tekst', '2linjer', '2 lines', 'horisontal', 'eng-logo',
    'uiblogo', '160-logo', 'positive', 'positiv', 'eng', 'gray', 'left', 'initialer',
];

function scoreFile(filename: string): number {
    const fl = filename.toLowerCase();
    if (DEFINITELY_NOT_LOGO.some(kw => fl.includes(kw))) return -999;
    let score = 0;
    if (GOOD_LOGO_KEYWORDS.some(kw => fl.includes(kw))) score += 100;
    if (fl.includes('icon')) score -= 10;
    if (fl.includes('crest')) score -= 5;
    if (fl.includes('colour') || fl.includes('color') || fl.includes('fullcolour') || fl.includes('full-colour')) score += 10;
    if (fl.includes('black') || fl.includes('white') || fl.includes('singlecolour') || fl.includes('monochrome')) score -= 10;
    if (fl.endsWith('.svg')) score += 20;
    if (fl.endsWith('.png')) score += 10;
    if (fl.endsWith('.webp')) score += 5;
    if (fl.endsWith('.jpg') || fl.endsWith('.jpeg')) score -= 5;
    return score;
}

async function detectPngBackground(filePath: string): Promise<{ hasBg: boolean; bgColor?: string }> {
    try {
        const img = sharp(filePath);
        const { width, height, channels } = await img.metadata();
        if (!width || !height || !channels) return { hasBg: false };
        const PATCH = 8;
        const corners = [{ left: 0, top: 0 }, { left: Math.max(0, width - PATCH), top: 0 }, { left: 0, top: Math.max(0, height - PATCH) }, { left: Math.max(0, width - PATCH), top: Math.max(0, height - PATCH) }];
        const hasAlpha = channels >= 4;
        let totalAlpha = 0, cornerR = 0, cornerG = 0, cornerB = 0;
        for (const corner of corners) {
            const { data } = await sharp(filePath).extract({ left: corner.left, top: corner.top, width: PATCH, height: PATCH }).raw().toBuffer({ resolveWithObject: true });
            const stride = hasAlpha ? 4 : 3;
            const pixelCount = data.length / stride;
            let patchAlpha = 0;
            for (let i = 0; i < data.length; i += stride) {
                cornerR += data[i]; cornerG += data[i + 1]; cornerB += data[i + 2];
                patchAlpha += hasAlpha ? data[i + 3] : 255;
            }
            totalAlpha += patchAlpha / pixelCount;
        }
        const avgAlpha = totalAlpha / corners.length;
        const isOpaque = !hasAlpha || avgAlpha >= 240;
        if (!isOpaque) return { hasBg: false };
        const pixCount = corners.length * PATCH * PATCH;
        const r = Math.round(cornerR / pixCount), g = Math.round(cornerG / pixCount), b = Math.round(cornerB / pixCount);
        return { hasBg: true, bgColor: `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}` };
    } catch { return { hasBg: false }; }
}

export async function GET(request: Request) {
    const { searchParams } = new URL(request.url);
    const domain = (searchParams.get('domain') || '').toLowerCase().trim();
    const fileParam = searchParams.get('file') || '';

    if (!domain) return new Response('No domain', { status: 400 });

    const uni = ALL_UNIVERSITIES.find(u => u.domain === domain);
    if (!uni) return new Response('Not found', { status: 404 });

    const logoDir = join(process.cwd(), 'public', uni.root, uni.folder, 'Logo');
    if (!existsSync(logoDir)) return new Response('No logo dir', { status: 404 });

    let chosen: string;
    if (fileParam) {
        // Normalise both to handle NFD (macOS) vs NFC (Standard/Web)
        const nfcFile = fileParam.normalize('NFC');
        const nfdFile = fileParam.normalize('NFD');

        // Recursive search for the file in logoDir
        function findFileRecursive(dir: string, target: string): string | null {
            const items = readdirSync(dir, { withFileTypes: true });
            for (const item of items) {
                const fullItemPath = join(dir, item.name);
                if (item.isDirectory()) {
                    const found = findFileRecursive(fullItemPath, target);
                    if (found) return found;
                } else if (/\.(png|svg|webp|jpg|jpeg)$/i.test(item.name)) {
                    // Check various normalization matches
                    const nf = item.name.normalize('NFC');
                    const nd = item.name.normalize('NFD');
                    const rel = fullItemPath.replace(logoDir + '/', '');
                    const nfcRel = rel.normalize('NFC');
                    const nfdRel = rel.normalize('NFD');

                    if (nf === nfcFile || nd === nfdFile || nf === nfdFile || nd === nfcFile || 
                        item.name === target || rel === target || nfcRel === nfcFile || nfdRel === nfdFile) {
                        return rel;
                    }
                }
            }
            return null;
        }

        const match = findFileRecursive(logoDir, fileParam);
        if (!match) return new Response('File not found', { status: 404 });
        chosen = match;
    } else {
        const allFiles = readdirSync(logoDir).filter(f => /\.(png|svg|webp|jpg|jpeg)$/i.test(f) && !f.startsWith('.'));
        if (allFiles.length === 0) return new Response('No logo', { status: 404 });
        const ranked = [...allFiles].sort((a, b) => scoreFile(b) - scoreFile(a));
        chosen = ranked[0];
    }

    const filePath = join(logoDir, chosen);
    if (!existsSync(filePath)) return new Response('File missing', { status: 404 });

    const ext = chosen.split('.').pop()!.toLowerCase();
    const contentType = ext === 'svg' ? 'image/svg+xml' : ext === 'webp' ? 'image/webp' : ext === 'png' ? 'image/png' : 'image/jpeg';

    let hasBg = ext === 'jpg' || ext === 'jpeg';
    let bgColor: string | undefined;

    // Add safety wrapper to prevent 500s on specific file glitches
    try {
        if (ext === 'png' || ext === 'webp') {
            const result = await detectPngBackground(filePath);
            hasBg = result.hasBg;
            bgColor = result.bgColor;
        }
    } catch (e) {
        console.error('Logo analysis failed:', e);
    }

    const buf = readFileSync(filePath);

    // OPTIMIZATION: If width is provided, resize the logo for faster loading
    const w = searchParams.get('w');
    if (w) {
        try {
            const width = parseInt(w);
            if (!isNaN(width) && width > 0) {
                const optimized = await sharp(buf)
                    .resize(width, null, { withoutEnlargement: true })
                    .webp({ quality: 85 })
                    .toBuffer();

                return new Response(new Uint8Array(optimized), {
                    headers: {
                        'Content-Type': 'image/webp',
                        'Cache-Control': 'public, max-age=3600',
                        'Access-Control-Allow-Origin': '*',
                        'Access-Control-Allow-Methods': 'GET, OPTIONS',
                    },
                });
            }
        } catch (e) {
            console.error('Logo optimization failed:', e);
        }
    }

    return new Response(new Uint8Array(buf), {
        headers: {
            'Content-Type': contentType,
            'Cache-Control': 'no-cache, no-store, must-revalidate',
            'Access-Control-Allow-Origin': '*',
            'Access-Control-Allow-Methods': 'GET, OPTIONS',
        },
    });
}

import { NextRequest, NextResponse } from 'next/server';
import sharp from 'sharp';
import { ImageResponse } from 'next/og';
import React from 'react';

const W = 1584, H = 396;

function hexToRgb(hex: string): { r: number; g: number; b: number } {
    const c = hex.replace('#', '').padEnd(6, '0');
    return {
        r: parseInt(c.slice(0, 2), 16) || 0,
        g: parseInt(c.slice(2, 4), 16) || 0,
        b: parseInt(c.slice(4, 6), 16) || 0,
    };
}

async function fetchBuf(url: string, origin: string): Promise<Buffer> {
    // QUALITY FIX: Strip optimization params like '&w=1600' to fetch the original high-rez master
    const cleanUrl = url.replace(/([?&])w=\d+&?/, '$1').replace(/[?&]$/, '');
    const fullUrl = cleanUrl.startsWith('/') ? `${origin}${cleanUrl}` : cleanUrl;

    const r = await fetch(fullUrl, { cache: 'no-store' });
    if (!r.ok) throw new Error(`Fetch failed (${r.status}): ${fullUrl}`);
    return Buffer.from(await r.arrayBuffer());
}

async function safeFetchPng(url: string, maxW: number, maxH: number, origin: string): Promise<Buffer | null> {
    try {
        const raw = await fetchBuf(url, origin);
        const meta = await sharp(raw).metadata();
        let pipeline = sharp(raw);
        if (meta.format === 'svg') {
            pipeline = sharp(raw, { density: 600 }); // High density for SVGs
        }
        return await pipeline
            .resize(maxW, maxH, { fit: 'inside', withoutEnlargement: true, background: { r: 0, g: 0, b: 0, alpha: 0 } })
            .ensureAlpha()
            .png()
            .toBuffer();
    } catch (e) {
        console.error('safeFetchPng error for', url, e);
        return null;
    }
}

export async function POST(req: NextRequest) {
    try {
        const host = req.headers.get('host') || 'myunibanner.vercel.app';
        const protocol = host.includes('localhost') ? 'http' : 'https';
        const origin = `${protocol}://${host}`;

        const body = await req.json();
        console.log('API render-banner body:', body);
        const {
            imageUrl,
            logoUrl,
            primaryHex = '#003865',
            layout = 0,
            text = '',
            photoFilter = 'none',
            logoScale = 1.0,
            textSize = 1.0,
        } = body as {
            imageUrl?: string | null;
            logoUrl?: string | null;
            primaryHex?: string;
            layout?: number;
            text?: string;
            logoIsLight?: boolean;
            photoFilter?: string;
            logoPos?: 'top' | 'bottom' | 'center';
            logoScale?: number;
            textSize?: number;
        };

        const primary = hexToRgb(primaryHex);
        const composites: sharp.OverlayOptions[] = [];

        // ── LAYOUT CALCULATIONS ──
        let PHOTO_W = W;
        let PHOTO_H = H;
        let PANEL_W = 0;
        let PANEL_X = 0;

        if (layout === 0) { PHOTO_W = 620; PANEL_W = W - 620; PANEL_X = 620; }
        else if (layout === 1) { PHOTO_W = W; PANEL_W = 550; PANEL_X = W - 550; }
        else if (layout === 2) { PHOTO_W = W; PANEL_W = 580; PANEL_X = W - 580; }
        else if (layout === 5) { PHOTO_W = W - 500; PANEL_W = 500; PANEL_X = W - 500; }
        else if (layout === 6) { PHOTO_W = Math.floor(W * 0.6); PANEL_W = Math.floor(W * 0.55); PANEL_X = W - PANEL_W; }

        // ── 1. Background photo ────────────────────────────────────────
        if (imageUrl) {
            try {
                const raw = await fetchBuf(imageUrl, origin);
                let pipeline = sharp(raw)
                    .resize(PHOTO_W, PHOTO_H, { fit: 'cover', position: 'center' });

                // ── APPLY CSS FILTERS ──
                if (photoFilter && photoFilter !== 'none') {
                    if (photoFilter.includes('grayscale(100%)')) {
                        pipeline = pipeline.grayscale();
                    }

                    // Simple regex to extract modulate parameters
                    const bMatch = photoFilter.match(/brightness\(([\d.]+)\)/);
                    const sMatch = photoFilter.match(/saturate\(([\d.]+)\)/);
                    const hMatch = photoFilter.match(/hue-rotate\(([-\d.]+)deg\)/);
                    const cMatch = photoFilter.match(/contrast\(([\d.]+)\)/);

                    const modulate: any = {};
                    if (bMatch) modulate.brightness = parseFloat(bMatch[1]);
                    if (sMatch) modulate.saturation = parseFloat(sMatch[1]);
                    if (hMatch) modulate.hue = parseFloat(hMatch[1]);

                    if (Object.keys(modulate).length > 0) {
                        pipeline = pipeline.modulate(modulate);
                    }

                    // Sharp's linear(a, b) can simulate contrast(a)
                    // contrast(X) in CSS is roughly linear(X, -(0.5 * X) + 0.5)
                    if (cMatch) {
                        const c = parseFloat(cMatch[1]);
                        pipeline = pipeline.linear(c, -(128 * c) + 128);
                    }

                    // Tints (Sepia-like)
                    if (photoFilter.includes('sepia(')) {
                        const sepMatch = photoFilter.match(/sepia\(([\d.]+)\)/);
                        const intensity = sepMatch ? parseFloat(sepMatch[1]) : 0.5;
                        // Tint with a warm color
                        pipeline = pipeline.tint({ r: 255, g: 240, b: 200 }); 
                    }
                }

                const finalBg = await pipeline.png().toBuffer();
                composites.push({ input: finalBg, top: 0, left: 0 });
            } catch (e) {
                console.error('BG image failed:', e);
            }
        }

        // ── 2. Panel overlay ───────────────────────────────────────────
        const PANEL_ALPHA = 232;

        if ([0, 1, 2, 5, 6].includes(layout)) {
            let panelBuffer: Buffer;

            if (layout === 2) {
                const mask = Buffer.from(
                    `<svg width="${PANEL_W}" height="${H}">
                        <polygon points="60,0 ${PANEL_W},0 ${PANEL_W},${H} 0,${H}" fill="white" />
                    </svg>`
                );
                panelBuffer = await sharp({ create: { width: PANEL_W, height: H, channels: 4, background: { ...primary, alpha: 255 } } })
                    .composite([{ input: mask, blend: 'dest-in' }])
                    .png().toBuffer();
            } else if (layout === 6) {
                const mask = Buffer.from(
                    `<svg width="${PANEL_W}" height="${H}">
                        <polygon points="120,0 ${PANEL_W},0 ${PANEL_W},${H} 0,${H}" fill="white" />
                    </svg>`
                );
                panelBuffer = await sharp({ create: { width: PANEL_W, height: H, channels: 4, background: { ...primary, alpha: 255 } } })
                    .composite([{ input: mask, blend: 'dest-in' }])
                    .png().toBuffer();
            } else {
                panelBuffer = await sharp({ create: { width: PANEL_W, height: H, channels: 4, background: { ...primary, alpha: layout === 0 ? 255 : PANEL_ALPHA } } })
                    .png().toBuffer();
            }

            composites.push({ input: panelBuffer, top: 0, left: PANEL_X });
        }


        // ── 3. Logo ───────────────────────────────────────────────────
        if (logoUrl) {
            // Match client SmartLogo h/maxW values per layout, scaled by user's logoScale
            const LOGO_BASE_H = layout === 6 ? 120 : layout === 7 ? 180 : layout === 4 ? 150 : 140;
            const LOGO_BASE_W = layout === 6 ? 360 : layout === 7 ? 400 : layout === 4 ? 400 : 380;
            const LOGO_MAX_H = Math.round(LOGO_BASE_H * logoScale);
            const LOGO_MAX_W = Math.round(LOGO_BASE_W * logoScale);

            const logoBuf = await safeFetchPng(logoUrl, LOGO_MAX_W, LOGO_MAX_H, origin);
            if (logoBuf) {
                const lm = await sharp(logoBuf).metadata();
                const lw = lm.width ?? LOGO_MAX_W;
                const lh = lm.height ?? LOGO_MAX_H;
                const textOffset = text ? Math.floor(lh * 0.35) : 0;

                let logoLeft: number, logoTop: number;

                if (PANEL_W > 0) {
                    logoLeft = PANEL_X + Math.floor((PANEL_W - lw) / 2) + (layout === 2 ? 30 : layout === 6 ? 60 : 0);
                    logoTop = Math.floor((H - lh) / 2) - textOffset;
                } else if (layout === 4) {
                    const lPos = body.logoPos || 'bottom';
                    logoLeft = W - lw - 40;
                    if (lPos === 'top') logoTop = 40;
                    else if (lPos === 'center') logoTop = Math.floor((H - lh) / 2);
                    else logoTop = H - lh - 40; // bottom
                } else {
                    // Centered layouts (3, 7)
                    logoLeft = Math.floor((W - lw) / 2);
                    logoTop = Math.floor((H - lh) / 2) - textOffset;
                }

                logoLeft = Math.max(0, Math.min(logoLeft, W - lw));
                logoTop = Math.max(0, Math.min(logoTop, H - lh));

                composites.push({ input: logoBuf, top: logoTop, left: logoLeft, blend: 'over' });
            }
        }

        // ── 4. Text Overlay ───────────────────────────────────────────
        if (text && text.trim().length > 0) {
            let panelW = 0, panelX = 0;
            if (layout === 0) { panelW = W - 620; panelX = 620; }
            else if (layout === 1) { panelW = 550; panelX = W - 550; }
            else if (layout === 2) { panelW = 580; panelX = W - 580; }
            else if (layout === 5) { panelW = 500; panelX = W - 500; }
            else if (layout === 6) { panelW = Math.floor(W * 0.55); panelX = W - panelW; }

            const MAX_LINE_LEN = 30;
            const words = text.split(/\s+/);
            const lines: string[] = [];
            let currentLine = '';
            words.forEach(word => {
                if ((currentLine + ' ' + word).trim().length <= MAX_LINE_LEN) {
                    currentLine = (currentLine + ' ' + word).trim();
                } else {
                    if (currentLine) lines.push(currentLine);
                    currentLine = word;
                }
            });
            if (currentLine) lines.push(currentLine);

            const finalLines = lines.slice(0, 3);

            let centerX: number, centerY: number;

            if (layout === 4) {
                const lPos = body.logoPos || 'bottom';
                const lBuf = composites.find(c => c.input && !c.input.toString().includes('svg'))?.input; // find the logo buffer
                // For Layout 4, the text should be to the left of the logo
                // Let's simplify: place it right-aligned with the logo area
                const LOGO_W_EST = 180; // approximate
                centerX = W - 40 - (LOGO_W_EST / 2) - 300; // Shifted left to clear logo
                if (lPos === 'top') centerY = 40 + 60;
                else if (lPos === 'center') centerY = Math.floor(H / 2);
                else centerY = H - 40 - 60;
            } else {
                centerX = panelW > 0 ? (panelX + (panelW / 2) + (layout === 2 ? 30 : layout === 6 ? 60 : 0)) : (W / 2);
                centerY = [0, 1, 2, 5, 6].includes(layout) ? 320 : layout === 3 ? 340 : 310;
            }

            const hColor = body.headlineColor || (body.logoIsLight ? '#ffffff' : '#111111');
            console.log(`Rendering text: "${text}" with color: ${hColor} at center: ${centerX},${centerY}`);

            const textWidth = Math.floor(panelW > 0 ? panelW + 100 : W);
            const textHeight = 150;
            const textLeft = Math.floor(centerX - textWidth / 2);
            const textTop = Math.floor(centerY - textHeight / 2) - 10;

            try {
                // Satori strictly requires an explicit font in Node API environments!
                // Fetching a fast, reliable bold TTF from Google Fonts to guarantee text renders.
                const fontRes = await fetch('https://fonts.gstatic.com/s/roboto/v30/KFOlCnqEu92Fr1MmYUtfBBc9.ttf');
                const fontData = await fontRes.arrayBuffer();

                const textImageRes = new ImageResponse(
                    React.createElement('div', {
                        style: {
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            justifyContent: 'center',
                            width: textWidth,
                            height: textHeight,
                            color: hColor,
                            fontSize: Math.round(30 * textSize),
                            fontWeight: 900,
                            lineHeight: 1.15,
                            letterSpacing: '-0.02em',
                            textAlign: 'center',
                            fontFamily: '"Roboto"',
                            background: 'transparent'
                        }
                    }, finalLines.map((line, i) => React.createElement('div', {
                        key: i,
                        style: { display: 'flex', justifyContent: 'center' }
                    }, line))),
                    { 
                        width: textWidth, 
                        height: textHeight,
                        fonts: [{
                            name: 'Roboto',
                            data: fontData,
                            weight: 900,
                            style: 'normal',
                        }]
                    }
                );

                const textImgBuffer = Buffer.from(await textImageRes.arrayBuffer());

                // Only composite if we got a valid image buffer
                if (textImgBuffer.length > 100) {
                    composites.push({ input: textImgBuffer, top: textTop, left: textLeft, blend: 'over' });
                } else {
                    console.error('ImageResponse produced an empty image buffer');
                }
            } catch (textErr) {
                console.error('Text overlay generation failed via ImageResponse:', textErr);
            }
        } else {
            console.log('Skipping text overlay: text is empty or missing.');
        }

        // ── 5. Compose ────────────────────────────────────────────────
        const usePhotoBase = !![0, 1, 2, 4, 5, 6, 7].includes(layout) && imageUrl;
        const baseColor = usePhotoBase ? { r: 0, g: 0, b: 0 } : primary;

        const output = await sharp({
            create: { width: W, height: H, channels: 3, background: baseColor }
        })
            .composite(composites)
            .png({ compressionLevel: 9, effort: 10 }) // Maximum PNG quality
            .toBuffer();

        return new NextResponse(new Uint8Array(output), {
            status: 200,
            headers: {
                'Content-Type': 'image/png',
                'Content-Disposition': 'attachment; filename="linkedin-banner.png"',
                'Content-Length': String(output.length),
                'Cache-Control': 'no-store',
            },
        });
    } catch (err) {
        console.error('render-banner error:', err);
        return NextResponse.json({ error: String(err) }, { status: 500 });
    }
}

// src/app/api/shopify-sync/route.ts
import { trackCustomerData } from '@/lib/shopify';
import { NextRequest, NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

/**
 * POST /api/shopify-sync
 * Syncs student registration data with Shopify Customer Fields
 */
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { customerId, schoolName, university, email } = body;

    if (!customerId || !schoolName || !university) {
      return NextResponse.json(
        { error: 'Missing required fields: customerId, schoolName, university' },
        { status: 400 }
      );
    }

    // Track customer data in Shopify
    const result = await trackCustomerData(customerId, schoolName, university);

    if (!result) {
      return NextResponse.json(
        { error: 'Failed to sync with Shopify' },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      message: 'Student data synced to Shopify',
      customerId,
      university,
    });
  } catch (error) {
    console.error('Shopify sync error:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

/**
 * GET /api/shopify-sync?customerId=xxx
 * Retrieves student data from Shopify
 */
export async function GET(request: NextRequest) {
  try {
    const customerId = request.nextUrl.searchParams.get('customerId');

    if (!customerId) {
      return NextResponse.json(
        { error: 'Missing customerId parameter' },
        { status: 400 }
      );
    }

    // Fetch customer data from Shopify
    const response = await fetch(
      `${process.env.NEXT_PUBLIC_SHOPIFY_STORE_URL}/admin/api/2026-01/customers/${customerId}.json`,
      {
        headers: {
          'X-Shopify-Access-Token': process.env.SHOPIFY_ADMIN_ACCESS_TOKEN || '',
        },
      }
    );

    if (!response.ok) {
      return NextResponse.json(
        { error: 'Customer not found' },
        { status: 404 }
      );
    }

    const data = await response.json();
    const metafields = data.customer.metafields || [];

    return NextResponse.json({
      customerId,
      email: data.customer.email,
      schoolName: metafields.find((m: any) => m.key === 'school_name')?.value,
      university: metafields.find((m: any) => m.key === 'university')?.value,
    });
  } catch (error) {
    console.error('Error fetching customer:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

