/* ═══════════════════════════════════════════════════════════════
   LAYOUT 1 — "IMMERSIVE"
═══════════════════════════════════════════════════════════════ */
function L1({ textSize = 1.0, textStyle = "blocky", logoScale = 1.0, brand, text, img, logoSrc, logoHasBg, logoIsLight, primary, headlineColor, bgOpacity = 100, tintIndex = 0, photoFilter = "none" }: LayoutProps) {
