export function searchUniversities(query: string, country?: string, limit = 6): University[] {
    try {
        const trimmed = query?.trim()?.toLowerCase() || "";
        let currentCountry = country;
        if (!country && typeof window !== "undefined") {
            try {
                const savedData = localStorage.getItem("lnbg_user_data");
                if (savedData && typeof savedData === "string") {
                    const parsed = JSON.parse(savedData);
                    if (parsed && typeof parsed === "object" && parsed.country) {
                        currentCountry = parsed.country;
                    }
                }
            } catch (e) {
                console.debug("Failed to parse user data from localStorage");
            }
        }

        // Strictly filter the pool by the selected country
        const pool = currentCountry 
            ? ALL_UNIVERSITIES.filter(u => u.country === currentCountry)
            : ALL_UNIVERSITIES;

        if (!trimmed) {
            return pool.slice(0, limit);
        }

        const queryWords = trimmed.split(/\s+/).filter(Boolean);

        const results = pool.filter(u => {
            try {
                const searchableText = [
                    u?.name || "",
                    u?.short || "",
                    u?.domain || "",
                    u?.country || "",
                    u?.root || "",
                    ...(u?.aliases || []),
                    ...(u?.campuses || [])
                ].join(" ").toLowerCase();

                return queryWords.every(word => searchableText.includes(word));
            } catch (e) {
                console.debug("Error filtering university:", e);
                return false;
            }
        });

        // Sort logic:
        // 1. Exact match on short name (abbreviation)
        // 2. Exact match on full name
        // 3. Country priority
        // 4. Alphabetical
        return results.sort((a, b) => {
            try {
                const aShortLower = a?.short?.toLowerCase() || "";
                const bShortLower = b?.short?.toLowerCase() || "";
                const aNameLower = a?.name?.toLowerCase() || "";
                const bNameLower = b?.name?.toLowerCase() || "";

                // Exact short match
                const aExactShort = aShortLower === trimmed;
                const bExactShort = bShortLower === trimmed;
                if (aExactShort && !bExactShort) return -1;
                if (!aExactShort && bExactShort) return 1;

                // Exact name match
                const aExactName = aNameLower === trimmed;
                const bExactName = bNameLower === trimmed;
                if (aExactName && !bExactName) return -1;
                if (!aExactName && bExactName) return 1;

                return aNameLower.localeCompare(bNameLower);
            } catch (e) {
                console.debug("Error sorting universities:", e);
                return 0;
            }
        }).slice(0, limit);
    } catch (e) {
        console.error("searchUniversities error:", e);
        return [];
    }
}

// src/hooks/useAiLayoutStyles.ts
import { LLMLayoutResponse } from "@/types/llm-layout";

/**
 * Hook to convert LLM design tokens to React inline styles & Tailwind classes
 * Bridges the gap between AI layout tokens and browser rendering
 */
export function useAiLayoutStyles(aiData: LLMLayoutResponse | null) {
  if (!aiData) {
    return {
      textContainerClass: "",
      textPositioningClass: "",
      textAlignClass: "text-left",
      maxWidthClass: "max-w-[520px]",
      colorTheme: "brand" as const,
      logoPlacement: "top-right",
      useGlassPanel: false,
    };
  }

  return {
    textContainerClass: `absolute ${aiData.design_tokens.text_positioning} ${aiData.design_tokens.max_width}`,
    textPositioningClass: aiData.design_tokens.text_positioning,
    textAlignClass: aiData.design_tokens.text_alignment,
    maxWidthClass: aiData.design_tokens.max_width,
    colorTheme: aiData.design_tokens.color_theme,
    logoPlacement: aiData.logo_config.placement,
    useGlassPanel: aiData.logo_config.use_glass_panel,
  };
}

/**
 * Parse Tailwind positioning classes into inline CSS styles
 * Example: "left-[600px] bottom-[42px]" → { left: "600px", bottom: "42px" }
 */
export function parseTailwindPosition(positioning: string): Record<string, string> {
  const styles: Record<string, string> = {};
  const tokens = positioning.split(/\s+/);

  tokens.forEach(token => {
    const match = token.match(/^(left|right|top|bottom)-\[([^\]]+)\]$/);
    if (match) {
      const [, prop, value] = match;
      styles[prop] = value;
    }
  });

  return styles;
}

/**
 * Get contrasting text color based on theme
 */
export function getTextColorFromTheme(theme: "dark" | "light" | "brand", brandColor?: string): string {
  switch (theme) {
    case "dark":
      return "#ffffff";
    case "light":
      return "#000000";
    case "brand":
    default:
      return "#ffffff"; // Assume white text on brand color
  }
}

// src/hooks/useShopifyTracking.ts
import { useEffect } from 'react';
import { trackPageView, trackEvent } from '@/lib/shopify';

export function useShopifyTracking(university?: string, eventName?: string) {
  useEffect(() => {
    // Track page view
    if (typeof window !== 'undefined') {
      trackPageView(window.location.pathname, university);
    }
  }, [university]);

  return {
    trackEvent: (event: string, data?: Record<string, any>) => {
      trackEvent(event, {
        university,
        ...data,
        timestamp: new Date().toISOString(),
      });
    },
  };
}

export function useStudentRegistration() {
  return {
    // Track when student completes onboarding
    trackOnboardingComplete: (studentData: {
      country: string;
      language: string;
      degree: string;
      year: string;
      industry: string;
      university: string;
    }) => {
      trackEvent('student_onboarding_complete', {
